args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?bd WHERE {
  VALUES ?person { dbr:Les_Briley dbr:Jean_Charles_Carbone }
  OPTIONAL { ?person dbo:birthDate ?bd1. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  BIND(coalesce(?bd1, ?bd2) AS ?bd)
  OPTIONAL { ?person rdfs:label ?personLabel . FILTER(lang(?personLabel) = "en") }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?older ?olderLabel ?olderBD ?younger ?youngerLabel ?youngerBD WHERE {
  VALUES ?p1 { dbr:Les_Briley }
  VALUES ?p2 { dbr:Jean_Charles_Carbone }

  OPTIONAL { ?p1 dbo:birthDate ?b1a. }
  OPTIONAL { ?p1 dbp:birthDate ?b1b. }
  BIND(coalesce(?b1a, ?b1b) AS ?b1)

  OPTIONAL { ?p2 dbo:birthDate ?b2a. }
  OPTIONAL { ?p2 dbp:birthDate ?b2b. }
  BIND(coalesce(?b2a, ?b2b) AS ?b2)

  FILTER(bound(?b1) && bound(?b2))

  BIND( IF(xsd:date(?b1) < xsd:date(?b2), ?p1, ?p2) AS ?older )
  BIND( IF(xsd:date(?b1) < xsd:date(?b2), ?b1, ?b2) AS ?olderBD )
  BIND( IF(xsd:date(?b1) < xsd:date(?b2), ?p2, ?p1) AS ?younger )
  BIND( IF(xsd:date(?b1) < xsd:date(?b2), ?b2, ?b1) AS ?youngerBD )

  OPTIONAL { ?older rdfs:label ?olderLabel . FILTER(lang(?olderLabel) = "en") }
  OPTIONAL { ?younger rdfs:label ?youngerLabel . FILTER(lang(?youngerLabel) = "en") }
}

